    {
      "@id": "activity:translation-team_1_bio-2026-07-09T13:57:59.667943+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T13:57:59.667943+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-team_1_bio",
      "@type": "prov:Entity",
      "prov:value": "Paul spent a decade as a teacher, four years working for edtechs, and has been experimenting with how to break learning out of books and classrooms for two decades. Peripateticware takes advantage of LLM advancements and leverages mobile technologies to allow students to learn from the world with guidance from their teachers wherever they choose to roam."
    },
    {
      "@id": "entity:target-team_1_bio-v1",
      "@type": "prov:Entity",
      "prov:value": "Paul on bir decade öğretmen olarak çalıştı, dörder yıl edtech şirketlerinde işledi ve okullardan ve kitaplardan öğrenmeyi nasıl kırarak mümkün kılabileceğini iki decade boyunca deniyor. Peripateticware LLM gelişimlerinden yararlanıyor ve mobil teknolojileri kullanıyor ki öğrenciler herhangi bir yerde öğrenebilsinler de öğretmenleri tarafından rehberlik görseler.",
      "generated_by": {
        "@id": "activity:translation-team_1_bio-2026-07-09T13:57:59.667943+00:00"
      },
      "used_source": {
        "@id": "entity:source-team_1_bio"
      }
    },
