    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "PDF veya CSV biçiminde resmî devlet eğitim standartlarını yükleyin (TEKS, NGSS, Common Core vb.). Ollama her standartı inceleme işlemi için çıkarır. Küresel olarak kaydedildiğinde, tüm öğretmenler ve evciler aktivitelerini bu standartlara göre haritalayabilirler. Aynı dosyayı yeniden yükledikten sonra işlem atlanır (checksum önbelleği).",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-09T13:58:22.003882+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
